tool_input.script:
export const meta = {
  name: 'site-studio-vnext-b-h',
  description: 'Site Studio runtime-vnext milestones B through H: worker families, tests, registry, recipe, operator cutover, legacy audit',
  phases: [
    { title: 'Foundation', detail: 'contract-validator' },
    { title: 'Bootstrap + Planning', detail: 'B + C planning workers' },
    { title: 'Content + Build', detail: 'C content/design/page workers' },
    { title: 'Components + Media', detail: 'D workers' },
    { title: 'SEO + QA + Proof', detail: 'E workers' },
    { title: 'Deploy', detail: 'F workers' },
    { title: 'Registry + Recipe', detail: 'integration wiring' },
    { title: 'Tests', detail: 'B-F test suites' },
    { title: 'Test Run + Fix', detail: 'run vitest, fix failures, write proof reports' },
    { title: 'G + H', detail: 'operator cutover + legacy audit' },
  ],
};

const BASE = '/Users/famtasticfritz/famtastic/site-studio';

const WORKER_INTERFACE = `
Each worker class follows this interface:
class XxxRunner {
  async execute(request, { runContext, stageAttempt, abortSignal }) {
    const start = process.hrtime.bigint();
    // ... work ...
    return { result, sideEffects: [], artifactReferences: [], durationMs: Number(process.hrtime.bigint() - start) / 1e6, costUsd: 0 };
  }
}
module.exports = { XxxRunner };

Workers write files to: path.join(runContext.workspace_root, 'staging', relativePath)
sideEffects: [{ path: relativePath, kind: 'write' }]
Use fs.mkdirSync(dir, { recursive: true }) before writing.
Use 'use strict'; at top. Only fs and path from stdlib (no external deps) unless specified.
Never throw — return error status in result when operations fail.
`;

const BUILD_REQUEST_FIXTURE = `
const buildRequest = {
  project_id: 'proj-1', run_id: 'run-1', site_tag: 'test-pools', product_type: 'site',
  deployment_mode: 'staging-only', architecture_preference: 'single-page',
  business: { name: 'Clean Pools', category: 'pool services', description: 'Pool cleaning in Tampa', location: 'Tampa, FL', public_contact: 'info@cleanpools.com', hours: 'Mon-Sat 8am-5pm' },
  positioning: { primary_cta: 'Get a Free Quote', primary_goal: 'book service', problem: 'dirty pool', desired_outcome: 'crystal clear water', audience: 'homeowners', ideal_customer: 'pool owners', secondary_cta: 'Learn More' },
  brand: { colors: { primary: '#0066cc', accent: '#ff6600' }, mood: 'professional', typography: 'modern sans-serif', style_references: [], do_not_do: [] },
  content_inputs: { services: [{ name: 'Weekly Cleaning', description: 'Sparkling results' }, { name: 'Chemical Treatment', description: 'Balanced water chemistry' }], about: 'Clean Pools has served Tampa for 10 years.', differentiators: ['Licensed', 'Insured', 'EPA certified'], testimonials: [], faqs: [], compliance_notes: [] },
  architecture_constraints: { required_pages: [], required_sections: [], rejected_patterns: [], must_support_forms: false },
  assets_available: { logo: null, photography: null, video: null, copy_docs: [], prior_site_assets: [] },
  component_opportunities: { reusable_component_candidates: [], component_sources_allowed: ['built-in'], custom_component_needed_flags: [] },
  media_opportunities: { missing_hero_media: true },
  seo_inputs: { target_geography: 'Tampa, FL', target_services: ['pool cleaning'], page_keywords: {}, schema_needs: ['LocalBusiness'] },
  deploy: { git_remote_target: null, netlify_site_linkage: null, staging_required: true, production_target_type: 'netlify', custom_domains: [], ssl_needs: false },
  authority: { can_publish_staging: false, can_prepare_prod_only: true, can_execute_prod_deploy: false },
};
`;

const TEST_SETUP = `
Use vitest. Import syntax:
  import { describe, it, expect, beforeEach, afterEach } from 'vitest';
  import os from 'os';
  import { mkdtempSync, rmSync, mkdirSync, existsSync, readFileSync, writeFileSync } from 'fs';
  import { createRequire } from 'module';
  const require = createRequire(import.meta.url);

Setup:
  let tmpDir;
  beforeEach(() => {
    tmpDir = mkdtempSync(os.tmpdir() + '/vnext-test-');
    mkdirSync(tmpDir + '/staging', { recursive: true });
    mkdirSync(tmpDir + '/outputs', { recursive: true });
  });
  afterEach(() => { rmSync(tmpDir, { recursive: true, force: true }); });
  const rc = () => ({ run_id: 'test-run-1', workspace_root: tmpDir, status: 'running' });
  const sa = () => ({ stage_attempt_id: 'atmp-1', stage_id: 'test', attempt_number: 1 });
`;

// Phase 1: Foundation
phase('Foundation');
await agent(`
Write ${BASE}/runtime-vnext/lib/contract-validator.js

This module validates typed build artifacts at stage boundaries.
Exports:
  validate(artifactType, data) — throws Error("Contract violation [Type]: reasons") if invalid
  SCHEMAS — object mapping type name to { validate(data): string[] } (returns error array)

Types and their required fields (check these; return error string per missing field):
  BuildRequest: project_id, run_id, site_tag, product_type, deployment_mode, architecture_preference, business (object), positioning (object), brand (object)
  ArchitectureDecision: architecture, page_count (must be number), route_model, layout_model, rejected_patterns (array), rationale
  SiteManifest: site_tag, site_name, pages (array), architecture
  PageManifest: page_id, route, title, purpose, required_sections (array), cta
  ContentPacket: page_id, headline, subheadline, primary_cta (object), sections (array)
  DesignTokenPack: colors (object), typography (object), spacing (object), css_output (string)
  ComponentPlan: page_id, components (array)
  MediaPlan: page_id, media_items (array)
  JsBehaviorPlan: modules (array)
  SeoPack: pages (array)
  BuildAssemblyManifest: site_tag, dist_root, pages (array), assets (array)
  QaReport: qa_type, status, checks (array)
  DeployReport: deploy_type, status
  ProofReport: run_id, site_tag, status, summary, artifacts (array)

Use 'use strict'. No external deps. Write the file using Write tool.
`, { label: 'contract-validator', phase: 'Foundation' });

// Phase 2: Bootstrap + Planning
phase('Bootstrap + Planning');
const [bResult, planResult] = await parallel([
  () => agent(`
Write these files for Milestone B (Bootstrap) of the Site Studio runtime-vnext rewrite:
  ${BASE}/runtime-vnext/families/repo-bootstrap-runner.js
  ${BASE}/runtime-vnext/families/config-scaffold-runner.js

${WORKER_INTERFACE}

### repo-bootstrap-runner.js
Input: request.buildRequest (BuildRequest), request.siteManifest (optional)
Output result: { files_created: string[], skipped: string[], stack: string, project_root: string }

Write to staging/:
- package.json: { name: buildRequest.site_tag, version: '0.1.0', description: buildRequest.business.description, private: true }
- .gitignore: standard Node.js gitignore (node_modules, .env, dist/, .DS_Store, *.log)
- README.md: # {business.name}\n{business.description}\n\n## Build\n{instructions}
- src/.gitkeep: empty file to scaffold src/ dir

Return: { files_created: [...], skipped: [], stack: 'html', project_root: 'staging' }

### config-scaffold-runner.js
Input: request.buildRequest, request.siteManifest (optional)
Output result: { files_created: string[], deploy_target: string, staging_url_template: string }

Write to staging/:
- .env.template: SITE_NAME={business.name}\nSITE_TAG={site_tag}\nDEPLOY_HOOK_URL=
- netlify.toml:
  [build]
  command = "echo 'static'"
  publish = "."
  [[redirects]]
  from = "/*"
  to = "/index.html"
  status = 200
- .env.example: same as .env.template but with example values filled in

Return: { files_created: [...], deploy_target: 'netlify', staging_url_template: 'https://{site_tag}.netlify.app' }
`, { label: 'milestone-b', phase: 'Bootstrap + Planning' }),

  () => agent(`
Write these files for Milestone C (Planning) of the Site Studio runtime-vnext rewrite:
  ${BASE}/runtime-vnext/families/architecture-decider-runner.js
  ${BASE}/runtime-vnext/families/sitemap-planner-runner.js

${WORKER_INTERFACE}

### architecture-decider-runner.js
Input: request.buildRequest
Output result (ArchitectureDecision): { architecture, page_count, route_model, layout_model, rejected_patterns, rationale }

Deterministic rules:
- preference 'single-page' → architecture='single-page', page_count=1, route_model='hash', layout_model='sections'
- preference 'multi-page' → architecture='multi-page', route_model='file-based', layout_model='full-page', page_count=Math.max(buildRequest.architecture_constraints?.required_pages?.length||0, 3)
- preference 'auto':
  - if rejected_patterns includes 'single-page' OR required_pages.length >= 4 → multi-page (same as above)
  - else → single-page
- preference 'app-like' → architecture='hybrid', route_model='spa', layout_model='app', page_count=1
- Always enforce: if architecture_constraints.rejected_patterns includes 'single-page', override to multi-page
- rejected_patterns: copy from architecture_constraints.rejected_patterns
- rationale: a short human-readable explanation

### sitemap-planner-runner.js
Input: request.buildRequest, request.architectureDecision (ArchitectureDecision)
Output result: { siteManifest: SiteManifest, pageManifests: PageManifest[] }

SiteManifest: { site_tag: buildRequest.site_tag, site_name: buildRequest.business.name, pages: [{page_id,route,title}], architecture }

For single-page: 1 PageManifest:
  { page_id: 'home', route: '/', title: 'Home', purpose: 'Primary landing page',
    required_sections: ['hero', 'services', 'about', 'cta', 'footer'],
    cta: buildRequest.positioning.primary_cta, dependencies: [] }

For multi-page: generate these PageManifests:
  home: { page_id: 'home', route: '/', sections: ['hero', 'services-overview', 'about-snippet', 'cta', 'footer'] }
  services: { page_id: 'services', route: '/services', sections: ['services-intro', 'services-grid', 'cta', 'footer'] }
  about: { page_id: 'about', route: '/about', sections: ['about-story', 'team', 'values', 'cta', 'footer'] }
  contact: { page_id: 'contact', route: '/contact', sections: ['contact-form', 'location', 'hours', 'footer'] }
  + any from buildRequest.architecture_constraints.required_pages (each: { page_id: slug(name), route: '/'+slug, ... })
  Set cta from buildRequest.positioning.primary_cta on each.
  Set purpose describing page goal.
  All sections arrays must include 'footer'.
`, { label: 'planning-workers', phase: 'Bootstrap + Planning' }),
]);

// Phase 3: Content + Build
phase('Content + Build');
const [contentResult, buildResult] = await parallel([
  () => agent(`
Write these content/design worker files for Milestone C:
  ${BASE}/runtime-vnext/families/page-copy-runner.js
  ${BASE}/runtime-vnext/families/design-token-runner.js
  ${BASE}/runtime-vnext/families/js-behavior-runner.js

${WORKER_INTERFACE}

### page-copy-runner.js
Input: request.buildRequest, request.pageManifest
Output result (ContentPacket): { page_id, headline, subheadline, primary_cta: {text,href}, sections: [{id,type,content}], meta_title, meta_description }

Build ContentPacket deterministically from buildRequest:
- headline: buildRequest.business.name + ' — ' + buildRequest.positioning.primary_goal
- subheadline: buildRequest.positioning.desired_outcome
- primary_cta: { text: buildRequest.positioning.primary_cta, href: '#contact' }
- For each section id in pageManifest.required_sections, produce a sections entry:
  - 'hero': content = { heading: business.name, body: positioning.problem + '. ' + positioning.desired_outcome, cta: primary_cta }
  - 'services'|'services-grid'|'services-overview'|'services-intro': content = { heading: 'Our Services', items: content_inputs.services.map(s=>({name:s.name,description:s.description})) }
  - 'about'|'about-snippet'|'about-story': content = { heading: 'About Us', text: content_inputs.about, differentiators: content_inputs.differentiators }
  - 'testimonials': content = { heading: 'What Clients Say', items: content_inputs.testimonials || [] }
  - 'cta'|'cta-banner': content = { heading: 'Ready to Get Started?', cta: positioning.primary_cta }
  - 'contact-form'|'contact': content = { heading: 'Contact Us', fields: ['name','email','message'] }
  - 'footer': content = { company: business.name, contact: business.public_contact, hours: business.hours }
  - 'team': content = { heading: 'Our Team', text: 'Serving ' + (business.location||'your area') }
  - 'values': content = { heading: 'Our Values', items: content_inputs.differentiators || [] }
  - 'location': content = { heading: 'Find Us', address: business.location, hours: business.hours }
  - 'hours': content = { heading: 'Hours', text: business.hours }
  - default: content = { heading: section_id.replace(/-/g,' '), text: business.name }
- meta_title: (business.name + ' | ' + (positioning.primary_goal||'Services') + ' | ' + (business.location||'')).substring(0,60)
- meta_description: (content_inputs.about||positioning.desired_outcome||'').substring(0,155)
- NEVER output '__PLACEHOLDER__' strings

### design-token-runner.js
Input: request.buildRequest
Output result (DesignTokenPack): { colors, typography, spacing, css_output }
sideEffects: [{ path: 'css/tokens.css', kind: 'write' }]

Derive colors from buildRequest.brand:
- If brand.colors.primary is set, use it; else derive from brand.mood:
  - 'professional'|'corporate'|'trust' → primary:#1e3a5f, secondary:#2c5282, accent:#c9a227, text:#1a202c, bg:#ffffff, surface:#f7fafc
  - 'energetic'|'bold'|'modern' → primary:#1a1a2e, secondary:#16213e, accent:#e94560, text:#2d3748, bg:#ffffff, surface:#edf2f7
  - 'natural'|'organic'|'wellness' → primary:#2d6a4f, secondary:#40916c, accent:#52b788, text:#1b4332, bg:#f9f4ef, surface:#d8f3dc
  - 'luxury'|'premium'|'elegant' → primary:#111111, secondary:#333333, accent:#d4af37, text:#111111, bg:#fafafa, surface:#f0ebe3
  - default → professional palette
- typography: detect from brand.typography string:
  - contains 'serif' or 'classic' → { heading_font: 'Georgia, serif', body_font: 'Garamond, Georgia, serif' }
  - else → { heading_font: 'Inter, system-ui, sans-serif', body_font: 'system-ui, -apple-system, sans-serif' }
  - Add: { base_size: '16px', scale: 1.25 }
- spacing: { xs:'4px', sm:'8px', md:'16px', lg:'24px', xl:'48px', '2xl':'80px' }
- css_output: build complete :root { --color-primary: X; --color-secondary: X; --color-accent: X; --color-text: X; --color-bg: X; --color-surface: X; --font-heading: X; --font-body: X; --size-base: 16px; --space-xs: 4px; --space-sm: 8px; --space-md: 16px; --space-lg: 24px; --space-xl: 48px; --space-2xl: 80px; }
- Write css_output to staging/css/tokens.css

### js-behavior-runner.js
Input: request.buildRequest, request.siteManifest, request.architectureDecision (optional)
Output result (JsBehaviorPlan): { modules: [{id, feature, output_path, code}] }
sideEffects: one entry per module

Generate self-contained minimal JS modules. Each module:
- Wraps logic in document.addEventListener('DOMContentLoaded', function() { ... });
- Is < 80 lines
- Has no external dependencies
- Write to staging/js/{id}.js

Always generate:
- nav.js (id:'nav', feature:'navigation'): mobile hamburger toggle — finds .nav-toggle and .nav-menu, toggles class 'open'
- smooth-scroll.js (id:'smooth-scroll', feature:'smooth-scroll'): querySelectorAll('a[href^="#"]'), scrollIntoView smooth

If architecture is 'single-page' or siteManifest has only 1 page:
- section-observer.js (id:'section-observer', feature:'active-nav'): IntersectionObserver to add .active class to nav link matching visible section id

If any page has contact-form or contact in required_sections:
- form-enhance.js (id:'form-enhance', feature:'form-validation'): basic email validation + success message
`, { label: 'content-workers', phase: 'Content + Build' }),

  () => agent(`
Write these page build/assembly workers for Milestone C:
  ${BASE}/runtime-vnext/families/page-builder-runner.js
  ${BASE}/runtime-vnext/families/shared-assets-runner.js
  ${BASE}/runtime-vnext/families/assembly-runner.js

${WORKER_INTERFACE}

### page-builder-runner.js
Input: request.buildRequest, request.pageManifest, request.contentPacket, request.designTokenPack,
       request.componentPlan (optional/null), request.mediaPlan (optional/null), request.seoPackSlice (optional)
Output result: { page_id, route, output_path, word_count, sections_rendered, has_media_placeholders }
sideEffects: [{ path: output_path, kind: 'write' }]

output_path: '/' → 'index.html'; '/about' → 'about.html'; etc. (strip leading slash, add .html)

Build a complete, valid HTML document (DOCTYPE through closing html tag):
- <head>: charset, viewport, title (seoPackSlice.title || contentPacket.meta_title || business.name), meta description, link to /css/tokens.css, /css/styles.css
- Nav: sticky header with site name + links. For multi-page use routes; for single-page use #section-id anchors.
  Include a mobile hamburger button.class='nav-toggle'. Nav links in ul.nav-menu.
- For each section in contentPacket.sections, render semantic HTML:
  - hero: <section class="hero" id="hero"><div class="container"><h1>{heading}</h1><p>{body}</p><a class="btn-primary" href="{cta.href||'#contact'}">{cta.text||'Get Started'}</a></div></section>
  - services/services-grid: <section class="services" id="services"><div class="container"><h2>{heading}</h2><div class="services-grid">{items.map(item=><div class="service-card"><h3>{item.name}</h3><p>{item.description}</p></div>)}</div></div></section>
  - about: <section class="about" id="about"><div class="container"><h2>{heading}</h2><p>{text}</p>{differentiators?<ul>...</ul>:''}</div></section>
  - testimonials: <section class="testimonials" id="testimonials"><div class="container"><h2>{heading}</h2>{items.map(t=><blockquote>...</blockquote>)}</div></section>
  - cta/cta-banner: <section class="cta-banner" id="cta"><div class="container"><h2>{heading}</h2><a class="btn-primary" href="#contact">{cta}</a></div></section>
  - contact-form/contact: <section class="contact" id="contact"><div class="container"><h2>{heading}</h2><form method="POST" action="#"><input type="text" name="name" placeholder="Your Name" required><input type="email" name="email" placeholder="Email Address" required><textarea name="message" rows="5" placeholder="Your Message" required></textarea><button type="submit" class="btn-primary">Send Message</button></form></div></section>
  - footer: <footer class="site-footer"><div class="container"><p>{company} | {contact} | {hours}</p><p>&copy; {company}</p></div></footer>
  - default: <section class="section {id}" id="{id}"><div class="container"><h2>{heading||id}</h2><p>{text||''}</p></div></section>
- Scripts at bottom: /js/nav.js, /js/smooth-scroll.js, /js/main.js
- Handle null/missing contentPacket.sections gracefully (render empty main if missing)
- word_count: rough count of text content
- has_media_placeholders: true if mediaPlan has any placeholder items

### shared-assets-runner.js
Input: request.buildRequest, request.siteManifest (optional), request.designTokenPack, request.jsBehaviorPlan (optional)
Output result: { css_files: ['css/styles.css'], js_files: ['js/main.js'], static_files: [] }
sideEffects: [{ path: 'css/styles.css', kind:'write' }, { path: 'js/main.js', kind:'write' }]

Write staging/css/styles.css — complete responsive stylesheet using CSS custom properties:
Include styles for: *, body, .container(max-width:1200px center), header, nav, .nav-toggle(hamburger), .nav-menu, .hero(min-height:80vh, flex center, gradient bg), .btn-primary, .services, .services-grid(CSS grid auto-fit), .service-card, .about, .testimonials, blockquote, .cta-banner, .contact, form inputs/textarea/button, footer
Include @media(max-width:768px) for: mobile nav, single-column, adjusted hero

Write staging/js/main.js:
Initialization script that sets up nav toggle and smooth scroll.
Use document.addEventListener('DOMContentLoaded', ...) pattern.

### assembly-runner.js
Input: request.buildRequest, request.siteManifest, request.pageArtifacts (array, may be empty),
       request.sharedAssetsReport, request.seoData (optional, has sitemap_xml and robots_txt strings)
Output result (BuildAssemblyManifest): { site_tag, dist_root, pages, assets, sitemap_xml, robots_txt, build_status, missing }
sideEffects: [sitemap.xml, robots.txt, build-manifest.json]

Logic:
- canonical = 'https://' + (buildRequest.site_tag||'site') + '.netlify.app'
- Generate sitemap.xml listing each page in siteManifest.pages
- Generate robots.txt: 'User-agent: *\nAllow: /\nSitemap: ' + canonical + '/sitemap.xml'
- Write sitemap.xml and robots.txt to staging/
- Check workspace_root/outputs/ for each page in siteManifest.pages → build_status
- Write staging/build-manifest.json with the full manifest
- dist_root: 'outputs/'
- missing: pages/assets expected but not found in outputs/
`, { label: 'build-workers', phase: 'Content + Build' }),
]);

// Phase 4: Components + Media
phase('Components + Media');
await agent(`
Write these component/media workers for Milestone D:
  ${BASE}/runtime-vnext/families/component-selector-runner.js
  ${BASE}/runtime-vnext/families/custom-component-builder-runner.js
  ${BASE}/runtime-vnext/families/media-planner-runner.js
  ${BASE}/runtime-vnext/families/media-generation-runner.js

${WORKER_INTERFACE}
CRITICAL: None of these workers may throw. Use try/catch and return error status.

### component-selector-runner.js
Input: request.pageManifest, request.designTokenPack (optional), request.buildRequest (optional)
Output result (ComponentPlan): { page_id, components: [{id,type,source,status,notes}], custom_needed: [], fallback_policy }

Map each section in pageManifest.required_sections to a component:
  hero → { id:'hero-comp', type:'hero', source:'built-in', status:'available', notes:'' }
  services|services-grid|services-overview|services-intro → { id:'services-grid-comp', type:'services-grid', source:'built-in', status:'available', notes:'' }
  about|about-snippet|about-story → { id:'about-comp', type:'about-section', source:'built-in', status:'available' }
  testimonials → { id:'testimonials-comp', type:'testimonials', source:'built-in', status:'available' }
  cta|cta-banner → { id:'cta-comp', type:'cta-banner', source:'built-in', status:'available' }
  contact-form|contact → { id:'contact-form-comp', type:'contact-form', source:'built-in', status:'available' }
  footer → { id:'footer-comp', type:'footer', source:'built-in', status:'available' }
  team → { id:'team-comp', type:'team-section', source:'built-in', status:'available' }
  values → { id:'values-comp', type:'values-section', source:'built-in', status:'available' }
  location|hours → { id: section+'-comp', type:section, source:'built-in', status:'available' }
  unknown → { id: section+'-comp', type:section, source:'custom-needed', status:'deferred', notes:'Custom build required' }
custom_needed: all sections with status 'deferred'
fallback_policy: 'use-built-in'
Wrap in try/catch → return { page_id:'unknown', components:[], custom_needed:[], fallback_policy:'use-built-in' } on error

### custom-component-builder-runner.js
Input: request.componentNeed ({ id, type, slot_in_page, page_id }), request.buildRequest (optional)
Output result: { component_id, type, output_path, status, metadata }
sideEffects: [{ path: 'components/{id}.html', kind: 'write' }] on success

Generate minimal HTML snippet, write to staging/components/{id}.html.
status: 'built' on success, 'deferred' on unknown type or any error.
Catch all errors, never throw.

### media-planner-runner.js
Input: request.pageManifest, request.contentPacket (optional), request.buildRequest
Output result (MediaPlan): { page_id, media_items: [{id,slot,status,source_type,path}], missing_ideal: [], has_blocking_media: false }

has_blocking_media: ALWAYS false — missing media uses placeholders.
For hero section → add hero-background item (status: buildRequest.assets_available?.photography ? 'available' : 'placeholder')
For services section → add service icon items (status: 'placeholder')
Wrap in try/catch, return empty MediaPlan on error.

### media-generation-runner.js
Input: request.mediaPlanItem ({ id, slot, source_type, path }), request.buildRequest (optional)
Output result: { id, status, output_path, source, prompt }

For source_type 'placeholder':
  Write SVG to staging/images/{id}.svg:
  '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="600"><rect width="1200" height="600" fill="#cccccc"/><text x="600" y="310" text-anchor="middle" font-size="32" fill="#666666">' + (slot||id) + '</text></svg>'
  Return { id, status:'placeholder', output_path:'images/'+id+'.svg', source:'placeholder', prompt:null }
  sideEffects: [{ path: 'images/'+id+'.svg', kind:'write' }]

For source_type 'generate':
  Return { id, status:'deferred', output_path:null, source:'generate', prompt:'Provider not configured' }
  sideEffects: []

Catch all errors → { id, status:'deferred', output_path:null, source:'error', prompt:null }, sideEffects:[]
`, { label: 'component-media-workers', phase: 'Components + Media' });

// Phase 5: SEO + QA + Proof
phase('SEO + QA + Proof');
const [seoQaRes, proofRes] = await parallel([
  () => agent(`
Write these SEO and QA workers for Milestone E:
  ${BASE}/runtime-vnext/families/seo-pack-runner.js
  ${BASE}/runtime-vnext/families/structural-qa-runner.js
  ${BASE}/runtime-vnext/families/content-qa-runner.js

${WORKER_INTERFACE}

### seo-pack-runner.js
Input: request.buildRequest, request.siteManifest, request.pageManifests (array), request.contentPackets (array, may be empty)
